function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }

// Wahrscheinlichkeitskalibrierung aus trading.simulation_trades (V1, Nachtrag zu
// docs/WAHRSCHEINLICHKEITSKALIBRIERUNG.md). segment_risk_bucket/segment_evidence_bucket/
// segment_time_horizon bleiben NULL - simulation_trades hat keine Entsprechung zu
// risk_score/evidence_confidence (die existieren nur auf trading.recommendations). Siehe
// Trading-Entscheidungszentrale.json ("Baue Query (Liste/Detail)") fuer den dazu passenden
// LEFT JOIN LATERAL-Konsumenten-Umbau.
const RULE_VERSION = 'wahrscheinlichkeitskalibrierung-simulation-v1';
const DATA_SOURCE = 'simulation_trades';

const rows = $('SQL: Aggregation (Simulation)').all().map(i => i.json);
const cfgRows = $('DB: Pipeline-Config laden (Wahrscheinlichkeit)').all().map(i => i.json);
const minSampleSize = (cfgRows.length && cfgRows[0].value_numeric != null) ? Number(cfgRows[0].value_numeric) : 30;

// DELETE+INSERT statt ON CONFLICT: Postgres behandelt NULL <> NULL in UNIQUE-Constraints, ein
// ON CONFLICT auf dem sql/071-Constraint (segment_risk_bucket/segment_evidence_bucket NULL)
// wuerde bei jedem Lauf Duplikate statt Updates erzeugen. Voller Refresh ist hier unproblematisch,
// da ohnehin bei jedem Lauf aus dem kompletten simulation_trades-Bestand neu aggregiert wird.
const parts = [];
parts.push(`DELETE FROM trading.probability_estimates WHERE data_source = ${pgStr(DATA_SOURCE)} AND rule_version = ${pgStr(RULE_VERSION)};`);

for (const r of rows) {
  const sampleSize = Number(r.sample_size);
  const status = sampleSize >= minSampleSize ? 'estimated' : 'insufficient_data';
  parts.push(`INSERT INTO trading.probability_estimates
    (segment_strategy, segment_direction, segment_market_regime, segment_risk_bucket, segment_evidence_bucket, segment_time_horizon,
     sample_size, p_win, p_positive_return, p_target_before_stop, expected_value_r, probability_status, min_sample_size_required,
     rule_version, data_source)
    VALUES (${pgStr(r.strategy)}, ${pgStr(r.direction)}, ${pgStr(r.market_regime_at_entry)}, NULL, NULL, NULL,
     ${pgNum(sampleSize)}, ${pgNum(r.p_win)}, ${pgNum(r.p_win)}, ${pgNum(r.p_target_before_stop)}, ${pgNum(r.expected_value_r)}, ${pgStr(status)}, ${pgNum(minSampleSize)},
     ${pgStr(RULE_VERSION)}, ${pgStr(DATA_SOURCE)});`);
}

const sql = `${parts.join('\n')}`;
return [{ json: { sql, row_count: rows.length, min_sample_size: minSampleSize } }];
